import{z as l,x as s,o as t,c as D,q as r,j as A,D as o,d as e,s as i,S as d,b as E}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"调试信息 DWARF","description":"","frontmatter":{"title":"调试信息 DWARF","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dwarf-debug-info.md","filePath":"cs/dwarf-debug-info.md","lastUpdated":1791413859000}'),B={name:"cs/dwarf-debug-info.md"};function p(C,a,c,F,u,f){const n=s("Mermaid");return t(),D("div",null,[a[2]||(a[2]=r('<h1 id="调试信息-dwarf" tabindex="-1">调试信息 DWARF <a class="header-anchor" href="#调试信息-dwarf" aria-label="Permalink to &quot;调试信息 DWARF&quot;">​</a></h1><div class="epigraph"><p>优化把值放进寄存器并删语句，源级调试靠 DWARF：行号表、位置列表、类型 DIE。信息必须随变换更新，否则断点落空。</p><footer>—— 据 DWARF 标准；Tichy 等调试优化代码的讨论；主干编译器通行证整理</footer></div><p>上一课<a href="/cs/stack-unwinding">unwind</a>用了 DWARF CFI。缺口是<strong>源级调试</strong>：哪一行、变量现在哪、类型布局。优化编译器要么保守少优化，要么发复杂 location list。本课钉 DIE 与行表，不写 GDB 协议。符号 mangling 下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>DCE 删赋值，变量「当前无位置」。内联：同一源行多个实例，需 <code>DW_TAG_inlined_subroutine</code>。缺口是<strong>元数据与 IR 同步</strong>，不是 FDE 查找。</p><p><span class="marginnote">DIE（Debugging Information Entry，调试信息条目）是 DWARF 描述世界的最小单位：一个变量、一个类型、一个函数各是一条，彼此用父子关系连成树——整个程序的类型世界就是一棵 DIE 树。可以类比 JSON：每条是一个带 tag 的对象，字段描述它的属性。</span></p><p>行号：<code>is_stmt</code> 标记语句边界，方便断点。调度打乱序，行表可非单调。</p><p><span class="marginnote">为什么优化必须同步更新行表：下断点时，调试器要在行表里找那一行对应的第一条指令；优化若把语句删了或挪了而不更新表，断点要么落不上、要么停在别的语句上——你以为是调试器坏了，其实是元数据过期。这就是正文「信息必须随变换更新」的具体含义。</span></p><h3 id="dwarf-不是「关掉优化」" tabindex="-1">DWARF 不是「关掉优化」 <a class="header-anchor" href="#dwarf-不是「关掉优化」" aria-label="Permalink to &quot;DWARF 不是「关掉优化」&quot;">​</a></h3><p><code>-O2 -g</code> 合法：信息尽量描述优化后的机器。质量参差。不要假设 <code>x</code> 总在栈槽。</p><p><span class="marginnote">DWARF 5。GCC/LLVM 的 DI 元数据。本课不把 CodeView 写完，只点名 MSVC 另一格式。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>前端发 <code>dbg.value</code>/<code>dbg.declare</code>。优化传递：复制、删除时更新。后端：寄存器分配后写成 location list（按 PC 区间）。类型：从语言类型降到 DIE。</p>',13)),(t(),A(d,null,{default:o(()=>[i(n,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E6%BA%90%E4%BD%8D%E7%BD%AE%22%5D%20--%3E%20DI%5B%22IR%20%E8%B0%83%E8%AF%95%E5%85%83%E6%95%B0%E6%8D%AE%22%5D%0A%20%20DI%20--%3E%20OPT%5B%22%E9%9A%8F%E4%BC%98%E5%8C%96%E6%9B%B4%E6%96%B0%22%5D%0A%20%20OPT%20--%3E%20DW%5B%22DWARF%20%E8%8A%82%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"与 SROA：字段拆开要多个 location。与合并：两变量同寄存器，调试器按 PC 区分。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,[e("体积："),E("code",null,"-g"),e(" 显著增大。分离："),E("code",null,".dwo"),e("/dsym。strip 后只留 unwind 或全无。不要把密钥写进调试字符串。")],-1)),(t(),A(d,null,{default:o(()=>[i(n,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E8%B0%83%E8%AF%95%E5%99%A8%EF%BC%9A%E7%8E%B0%E5%9C%A8%E5%8F%98%E9%87%8F%20x%20%E5%9C%A8%E5%93%AA%EF%BC%9F%22%5D%20--%3E%20PC%5B%22%E5%85%88%E7%9C%8B%E5%BD%93%E5%89%8D%E5%81%9C%E5%9C%A8%E5%93%AA%E6%9D%A1%E6%8C%87%E4%BB%A4%EF%BC%88PC%EF%BC%89%22%5D%0A%20%20PC%20--%3E%20R1%5B%22PC%20%E5%9C%A8%200x100-0x1FF%EF%BC%9A%E6%9F%A5%E8%A1%A8%E5%BE%97%20x%20%E5%9C%A8%E5%AF%84%E5%AD%98%E5%99%A8%20RDI%22%5D%0A%20%20PC%20--%3E%20R2%5B%22PC%20%E5%9C%A8%200x200-0x2FF%EF%BC%9Ax%20%E8%A2%AB%E6%BA%A2%E5%87%BA%EF%BC%8C%E8%BA%BA%E5%9C%A8%E6%A0%88%E6%A7%BD%E9%87%8C%22%5D%0A%20%20PC%20--%3E%20R3%5B%22PC%20%E5%9C%A8%200x300%20%E4%B9%8B%E5%90%8E%EF%BC%9Ax%20%E5%B7%B2%E8%A2%AB%E4%BC%98%E5%8C%96%E5%88%A0%E9%99%A4%EF%BC%8C%E6%97%A0%E4%BD%8D%E7%BD%AE%22%5D%0A%20%20R1%20--%3E%20A%5B%22%E5%90%8C%E4%B8%80%E5%8F%98%E9%87%8F%EF%BC%8C%E4%BD%8D%E7%BD%AE%E9%9A%8F%E6%8C%87%E4%BB%A4%E5%8C%BA%E9%97%B4%E5%88%87%E6%8D%A2%22%5D%0A%20%20R2%20--%3E%20A%0A%20%20R3%20--%3E%20A%0A"})]),fallback:o(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">strip 直译「剥离」：把调试节从二进制里剪下来单独存放（.dwo 或 dSYM 一类），发行物变小，出问题时再把两半拼回去调。常见误区：strip 不改变程序行为——剪掉的只是「给人和调试器看的注释」，机器执行根本不读它们。</span></p><p>ASan 改变布局，调试信息要跟。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写表达式求值器全部 DWARF ops。后课默认：优化代码用位置列表。下一课符号与 mangling：链接与调试都看见的名字。</p><p>也不把 DWARF 当核心转储格式的全部（ELF note 另有）。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DWARF：行号、类型、变量位置，随优化更新。</li><li>内联与 SSA 析构是主要难点。</li><li>CFI 是 DWARF 的一部分，服务展开。</li><li>出处：DWARF 标准；对照 Appel/龙书调试支持。</li></ul>',7))])}const g=l(B,[["render",p]]);export{h as __pageData,g as default};
